CREATE TABLE IF NOT EXISTS pairings(id TEXT PRIMARY KEY, first_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, second_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, first_decision TEXT NOT NULL DEFAULT 'pending' CHECK(first_decision IN('pending','yes','no')), second_decision TEXT NOT NULL DEFAULT 'pending' CHECK(second_decision IN('pending','yes','no')), created INTEGER NOT NULL, CHECK(first_user<second_user), UNIQUE(first_user,second_user));
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY, pair_id TEXT NOT NULL UNIQUE REFERENCES pairings(id) ON DELETE CASCADE, activity TEXT NOT NULL, starts_at INTEGER NOT NULL, place TEXT NOT NULL, cost TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, confirmed_first INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_first IN(0,1)), confirmed_second INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_second IN(0,1)), cancelled INTEGER NOT NULL DEFAULT 0 CHECK(cancelled IN(0,1)), created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS pairings_second_user ON pairings(second_user,created);
